<div role="tab" class="tab" tabindex="0" data-bind="
    attr: {
        id: id,
        'aria-label': viewModel.displayName,
        'aria-selected': isSelected() ? 'true' : 'false',
        'draggable': canReorder
    },
    css: {
        active: viewModel.isActive,
        temporary: viewModel.isTemporary,
        'reorder-over': viewModel.reorderOver
    },
    event: {
        dblclick: (data, event) => viewModel.tabPanel.openTab(data.viewModel, true),
        keydown: (data, event) => viewModel.tabPanel.tabKeyDown(data.viewModel, event),
        focus: (data, event) => viewModel.tabPanel.tabFocus(data.viewModel, event),
        contextmenu: (data, event) => viewModel.tabPanel.openTabContextMenu(data.viewModel, event),
        mousedown: (data, event) => viewModel.tabPanel.onMouseDown(data.viewModel, event),
        mouseup: (data, event) => viewModel.tabPanel.onMouseUp(data.viewModel, event),
        dragstart: (data, event) => viewModel.tabPanel.onDragStart(data.viewModel, event),
        dragenter: (data, event) => viewModel.tabPanel.onDragEnter(data.viewModel, event),
        dragleave: (data, event) => viewModel.tabPanel.onDragLeave(data.viewModel, event),
        dragover: (data, event) => viewModel.tabPanel.onDragOver(data.viewModel, event),
        drop: (data, event) => viewModel.tabPanel.onDrop(data.viewModel, event)
    },
    click: (data, event) => viewModel.tabPanel.openTab(data.viewModel, false),
    clickBubble: false,
    hasFocus: viewModel.mainSpanFocused
">
    <div class="tab-area">
        <div class="tab-active-indicator"></div>

        <div class="tab-inner-area" data-bind="style: { background: backgroundColor }">
            <!-- ko if: hasIcon() && isNamedIcon() -->
            <se-icon params="with: { name: viewModel.icon }"></se-icon>
            <!-- /ko -->

            <!-- ko if: hasIcon() && !isNamedIcon() -->
            <span class="icon" data-bind="icon: viewModel.icon"></span>
            <!-- /ko -->

            <div class="tab-name-container">
                <span class="tab-name" data-bind="attr: { title: viewModel.fullName }, text: viewModel.displayName"></span>
                <!-- ko if: hasDisplayPath -->
                <span class="tab-path" data-bind="text: viewModel.displayPath" ></span>
                <!-- /ko -->
            </div>

            <!-- ko if: !!viewModel.isTemporary() || !!viewModel.tabPanel.canCloseTabs() -->
            <ul class="tab-button-container" role="toolbar">
                <!-- ko if: viewModel.isTemporary() -->
                <li role="presentation">
                    <button class="tab-button preview-tab-icon" data-bind="
                        click: viewModel.tabPanel.promoteTemporaryTab,
                        clickBubble: false,
                        hasFocus: viewModel.keepOpenFocused,
                        accessibility: { enter: viewModel.tabPanel.promoteTemporaryTab },
                        attr: { title: viewModel.keepOpenButtonLabel }"
                    >
                        <se-icon params="with: { name: 'PromoteTab' }"></se-icon>
                    </button>
                </li>
                <!-- /ko -->

                <!-- ko if: viewModel.tabPanel.canCloseTabs() -->
                <li role="presentation">
                    <button class="tab-button close-tab-icon" data-bind="
                        click: (data) => viewModel.tabPanel.closeTab(data.viewModel),
                        clickBubble: false,
                        hasFocus: closeFocused,
                        accessibility: { enter: () => viewModel.tabPanel.closeTab($data.viewModel) },
                        attr: { title: viewModel.closeButtonLabel },
                        event: {
                            mouseover: () => closeButtonHovered(true),
                            mouseout: () => closeButtonHovered(false)
                        }"
                    >
                        <se-icon params="with: { name: closeIcon }"></se-icon>
                    </button>
                </li>
                <!-- /ko -->
            </ul>
            <!-- /ko -->
        </div>
    </div>

    <div class="tab-right-border"></div>
    <div class="tab-bottom-border"></div>
</div>
